import { apiRequest } from './client';
import { ENDPOINTS } from './endpoints';
import { getCachedUser } from '../utils/auth';
const departments = ['IT', 'HR', 'Facilities', 'Finance', 'Legal', 'Engineering'];
const urgencies = ['Low', 'Medium', 'High', 'Critical'];
const asDepartment = (value) => departments.includes(value) ? value : 'IT';
const asUrgency = (value) => urgencies.includes(value) ? value : 'Medium';
export function mapTicket(raw) {
    const info = raw.ticket_info;
    const audit = raw.rag_audit_trail;
    const id = String(raw.ticket_id ?? raw.id ?? info?.ticket_id ?? '');
    const user = raw.user;
    const status = String(raw.status ?? 'QUEUED');
    const statusMap = { QUEUED: 'Processing', PROCESSED: 'Pending Review', RESOLVED: 'Resolved', ESCALATED: 'Escalated', FAILED: 'Failed' };
    return {
        id, threadId: String(raw.thread_id ?? `ticket_thread_${id}`), subject: String(raw.subject ?? info?.subject ?? ''), description: String(raw.body ?? raw.description ?? info?.original_body ?? ''),
        status: statusMap[status] ?? (info ? 'Pending Review' : 'Processing'), department: asDepartment(raw.department ?? info?.department), urgency: asUrgency(raw.priority ?? info?.priority),
        createdAt: String(raw.created_at ?? new Date().toISOString()), userEmail: String(user?.email ?? raw.email ?? ''),
        userTier: String(raw.account_tier ?? info?.account_tier ?? user?.account_tier ?? 'Standard'), aiPredictedDept: asDepartment(raw.department ?? info?.department),
        aiConfidence: Number(raw.eval_confidence ?? raw.confidence ?? info?.confidence ?? audit?.confidence_score ?? 0), aiRagSolution: String(raw.final_response_text ?? raw.resolution ?? raw.ai_draft?.full_response_text ?? ''), latencyMs: Number(raw.total_latency ?? raw.latency ?? raw.latency_ms ?? 0),
        initialLatency: Number(raw.initial_latency ?? 0), totalLatency: Number(raw.total_latency ?? raw.latency ?? 0),
        groundingScore: Number(audit?.confidence_score ?? raw.grounding_score ?? 0), isHallucinated: Boolean(audit?.has_hallucinations ?? raw.has_hallucinations),
        groundingSourceIds: Array.isArray(audit?.grounding_source_ids) ? audit?.grounding_source_ids.map(String) : [],
        retrievedDocs: Array.isArray(audit?.retrieved_docs) ? audit?.retrieved_docs : [],
        aiDraft: raw.ai_draft ?? undefined,
        slaStatus: slaStatus(raw.created_at, raw.status, raw.account_tier ?? user?.account_tier, raw.priority),
    };
}
function slaStatus(createdAt, status, tier, priority) {
    if (String(status) === 'RESOLVED')
        return 'Healthy';
    const ageHours = (Date.now() - new Date(String(createdAt)).getTime()) / 3_600_000;
    const limit = String(tier).toLowerCase() === 'enterprise' ? 4 : 24;
    const isAtRiskAccount = String(tier).toLowerCase() === 'enterprise' || String(priority).toLowerCase() === 'critical';
    return ageHours >= limit ? 'Breached' : isAtRiskAccount && ageHours >= limit * 0.75 ? 'At Risk' : 'Healthy';
}
export async function fetchTickets() {
    const path = getCachedUser()?.role === 'admin' ? ENDPOINTS.adminTickets.list : ENDPOINTS.tickets.mine;
    return (await apiRequest(path)).map(mapTicket);
}
export async function fetchTicketById(id, admin = getCachedUser()?.role === 'admin') { return mapTicket(await apiRequest(admin ? ENDPOINTS.adminTickets.byId(id) : ENDPOINTS.tickets.byId(id))); }
export async function createTicket(input) {
    const form = new FormData();
    form.append('subject', input.subject);
    form.append('body', input.description);
    input.imageFiles?.forEach((file) => form.append('new_ticket_images', file));
    return mapTicket(await apiRequest(ENDPOINTS.tickets.create, { method: 'POST', body: form }));
}
export async function approveTicket(input) {
    const result = await apiRequest(ENDPOINTS.tickets.approval(input.threadId ?? input.id), { method: 'POST', body: { decision: 'APPROVE', edited_text: input.solution } });
    return mapTicket({ ...result, id: input.id, status: 'RESOLVED', final_response_text: input.solution });
}
export async function rejectTicket(id, threadId) {
    const result = await apiRequest(ENDPOINTS.tickets.approval(threadId ?? id), { method: 'POST', body: { decision: 'REJECT_AND_ESCALATE' } });
    return mapTicket({ ...result, id, status: 'ESCALATED' });
}
export function fetchProcessedTickets() { return apiRequest(ENDPOINTS.adminTickets.processed); }
export function resolveProcessedTicket(payload) { return apiRequest(ENDPOINTS.adminTickets.resolve(payload.ticket_id), { method: 'POST', body: payload }); }
export function fetchPendingTickets() { return apiRequest(ENDPOINTS.adminTickets.pending); }
export function fetchIncidentAnalysis() { return apiRequest(ENDPOINTS.adminTickets.analyzeIncidents); }
export function fetchAdminTicketById(id) { return apiRequest(ENDPOINTS.adminTickets.byId(id)); }
export function fetchAdminUserTickets(id) { return apiRequest(ENDPOINTS.adminTickets.forUser(id)); }
export function fetchUsers() { return apiRequest(ENDPOINTS.users.list); }
export function fetchUserProfile() { return apiRequest(ENDPOINTS.users.profile); }
export function fetchUserById(id) { return apiRequest(ENDPOINTS.users.byId(id)); }
export function fetchTicketStatus(id) { return apiRequest(ENDPOINTS.tickets.status(id)); }
export function fetchLatestAlert() { return apiRequest(ENDPOINTS.adminTickets.latestAlert); }
export function fetchInternalTickets(query = '') { return apiRequest(`${ENDPOINTS.internalAdmin.list}${query ? `?${query}` : ''}`); }
export function fetchInternalTicketById(id) { return apiRequest(ENDPOINTS.internalAdmin.byId(id)); }
export function fetchInternalUserTickets(id) { return apiRequest(ENDPOINTS.internalAdmin.forUser(id)); }
export function submitEngineerResolution(id, body) { return apiRequest(ENDPOINTS.tickets.engineerResolution(id), { method: 'PUT', body }); }
export function submitTicketReward(id, body) { return apiRequest(ENDPOINTS.tickets.reward(id), { method: 'PUT', body }); }
export function checkModelHealth() { return apiRequest(ENDPOINTS.model.health, { auth: false }); }
export async function fetchAnalytics() {
    const metrics = await apiRequest(ENDPOINTS.adminTickets.analytics);
    return {
        volumes: [],
        routingAccuracy: Number.parseFloat(metrics.routing_accuracy ?? '0') / 100,
        aiResolutionRate: Number.parseFloat(metrics.ai_resolution_rate ?? '0'),
        escalationRate: Number.parseFloat(metrics.escalation_rate ?? '0'),
        avgSlaResolutionTime: 0, p50Latency: 0, p95Latency: 0, p99Latency: 0, ragGroundingAvg: 0,
        ragRetryRate: 0,
    };
}
const authUser = (response, role) => ({ id: String(response.user.id), name: response.user.name ?? response.user.business_name ?? response.user.email, email: response.user.email, role, tier: response.user.account_tier });
export async function userLogin(email, password) {
    const response = await apiRequest(ENDPOINTS.auth.login, { method: 'POST', auth: false, body: { email, password } });
    return { user: authUser(response, 'user'), token: response.token };
}
export async function adminLogin(email, password) {
    const response = await apiRequest(ENDPOINTS.auth.adminLogin, { method: 'POST', auth: false, body: { email, password } });
    return { user: authUser(response, 'admin'), token: response.token };
}
